const output = [];
for (const item of $input.all()) {
  const input = item.json.body ?? item.json;
  const errors = [];
  if (!input || typeof input !== 'object') errors.push('payload must be an object');
  const eventId = input?.event_id ?? input?.request_id ?? `demo-${Date.now()}`;
  if (!input?.email && 'order' === 'appointment') errors.push('email is required');
  if (!input?.question && 'order' === 'question') errors.push('question is required');
  if (!input?.order_id && 'order' === 'order') errors.push('order_id is required');
  if (!input?.invoice_number && 'order' === 'invoice') errors.push('invoice_number is required');
  if (errors.length) {
    output.push({json: {ok: false, event_id: eventId, errors}});
    continue;
  }
  let result = {ok: true, event_id: eventId, workflow: 'order', processed_at: new Date().toISOString()};
  if ('order' === 'report') {
    const rows = Array.isArray(input) ? input : (input.sales ?? []);
    const total = rows.reduce((sum, row) => sum + Number(row.amount ?? 0), 0);
    result.metrics = {count: rows.length, total: Number(total.toFixed(2)), average: rows.length ? Number((total / rows.length).toFixed(2)) : 0, alert: rows.length > 0 && total < 100};
  } else if ('order' === 'question') {
    result.answer = input.document_context ? input.document_context : 'No encontré información suficiente en el contexto proporcionado.';
    result.grounded = Boolean(input.document_context);
  } else if ('order' === 'invoice') {
    const expected = Number(input.subtotal ?? 0) + Number(input.tax ?? 0);
    result.invoice = {...input, validation: {expected_total: Number(expected.toFixed(2)), matches: Math.abs(expected - Number(input.total ?? 0)) < 0.01}};
  } else if ('order' === 'order') {
    const items = Array.isArray(input.items) ? input.items : [];
    result.order = {...input, total: Number(items.reduce((s, x) => s + Number(x.quantity ?? 0) * Number(x.unit_price ?? 0), 0).toFixed(2))};
  } else {
    result.record = input;
    result.next_action = 'order' === 'appointment' ? 'Check calendar availability and send confirmation' : 'Continue with the next business system';
  }
  output.push({json: result});
}
return output;
